from html import escape as e
from fractions import Fraction as F
SOURCES=[
 dict(id='uk-efficiency',title='HM Treasury · The Government Efficiency Framework',url='https://www.gov.uk/government/publications/the-government-efficiency-framework/the-government-efficiency-framework--2',published=None,updated='2025-11-24',checked='2026-10-27',kind='영국 중앙정부의 효율 보고 지침',note='페이지 표시 갱신2025-11-24,2026-10-27 원문 §4.1·4.4–4.8 확인. 현금 지출 감소와 비현금 편익·비용 경계·중복 계산 구분을 참고. 최초 발행일이나 모든 조항의 발효일로 해석하지 않음. 영국의 보고 의무를 한국·민간 조직이나 PMP의 공식 계산 규칙으로 적용하지 않음. 원문의 수치 예제·그림을 복제하지 않은 창작 사례.'),
 dict(id='ni-benefits',title='Northern Ireland Department of Finance · Introduction to benefits management',url='https://www.finance-ni.gov.uk/articles/introduction-benefits-management-programmes-and-projects',published=None,checked='2026-10-27',kind='북아일랜드 정부의 프로그램·프로젝트 실무 지침',note='2026-10-27 원문의 책임·사업 검토 절 확인. 기준 상태·다른 프로젝트와의 경계·사업성 갱신·전환 뒤 책임을 보는 관점 참고. 페이지 최초 발행일은 확인하지 못했으며 최신 전면 개정으로 주장하지 않음. 아래 역할·측정 계획·판단 기록은 자체 제작이며 원문의 조직 체계를 모든 조직에 적용하지 않음.')]
DATA={'requests':1200,'users':100,'trained':90,'active':60,'axisMaxHours':300,
 'periods':[{'id':'before','label':'도입 전 한 달','firstMinutes':12,'reworkRate':[1,10],'reworkMinutes':20},
            {'id':'after','label':'도입 후 한 달','firstMinutes':8,'reworkRate':[1,5],'reworkMinutes':20}],
 'referenceHourlyWon':30000,'additionalMonthlyCashWon':300000,
 'targets':{'activePercent':80,'totalHours':220,'maxReworkPercent':10}}
def render():
 out='''<section class="benefit-study article-section"><span class="eyebrow">BENEFIT REALISATION / 분모와 돈의 경계</span><h3>“4분 빨라졌다”에서 멈추면 무엇을 놓칠까요?</h3><p>가상 접수 서비스의 운영 도입 사례입니다. 앞의 승인 처리시간5일→3일 목표와는 별개예요. 배포·교육·실사용·처리 시간·현금 지출을 따로 관찰합니다. 아래 값은 실제 회사의 성과나 기출 수치가 아닙니다.</p><div class="benefit-chain" aria-label="산출물부터 편익까지의 가설"><section><b>산출물</b><p>기능 배포와 운영 인계</p></section><span aria-hidden="true">→</span><section><b>행동·성과</b><p>실사용과 재작업 포함 시간</p></section><span aria-hidden="true">→</span><section><b>편익·증거</b><p>사용 가능한 여력과 서비스 개선</p></section></div><p class="small muted">화살표는 확인해야 할 가설입니다. 배포·교육 수료가 뒤의 성과를 자동 보장하지 않아요.</p><h3>비교할 대상을 먼저 고정해요</h3><p>전후 각각 한 달, 같은 유형·난이도로 정규화한 요청1,200건이 전부 종료됐다고 가정합니다. 기본 처리는 재작업을 제외한 건당 작업 시간이며, 재작업 대상 건은 각각 추가20분이 한 번만 발생합니다. 두 시간을 겹쳐 세지 않습니다. 대기·교육·지원·관리 시간은 이 단순 계산 밖에 있어요.</p><div class="tco-table-scroll"><table class="benefit-values"><caption>가상 월간 작업 기록 · 사람의 투입 시간이며 고객의 대기·처리 경과시간과 다릅니다</caption><thead><tr><th scope="col">측정 항목</th><th scope="col">도입 전</th><th scope="col">도입 후</th></tr></thead><tbody><tr><th scope="row">종료한 적격 요청</th><td>1,200건</td><td>1,200건</td></tr><tr><th scope="row">기본 처리 · 재작업 제외</th><td>건당12분</td><td>건당8분</td></tr><tr><th scope="row">추가 재작업 대상</th><td>10% · 120건</td><td>20% · 240건</td></tr><tr><th scope="row">대상 건당 추가 재작업</th><td>20분 · 1회</td><td>20분 · 1회</td></tr><tr><th scope="row">기본 처리 투입 시간</th><td>1,200×12÷60 = 240시간</td><td>1,200×8÷60 = 160시간</td></tr><tr><th scope="row">추가 재작업 시간</th><td>120×20÷60 = 40시간</td><td>240×20÷60 = 80시간</td></tr><tr class="benefit-total"><th scope="row">비교 경계 안의 합계</th><td>280시간</td><td>240시간</td></tr></tbody></table></div><p>기본 처리만 보면80시간 감소입니다. 재작업은40시간 늘어 합계 감소는40시간입니다. 기준280시간 대비40÷280≈14.3% 감소예요. 재작업을 보지 않고80시간 절감이라고 보고하면 이 경계의 감소를 두 배로 보입니다.</p><div class="benefit-chart"><p class="small muted">0~300시간의 같은 축 · 기본 처리와 추가 재작업의 합</p><div class="benefit-legend"><span><i class="benefit-first"></i>기본 처리</span><span><i class="benefit-rework"></i>추가 재작업</span></div><div class="benefit-axis" aria-hidden="true">'''
 out+=''.join('<span style="left:'+str(v/3)+'%">'+str(v)+'</span>' for v in [0,100,200,300])+'</div>'
 for d in DATA['periods']:
  first=F(DATA['requests']*d['firstMinutes'],60);rework=F(DATA['requests']*d['reworkRate'][0]*d['reworkMinutes'],d['reworkRate'][1]*60)
  out+='<section class="benefit-bar-row" data-benefit-period="'+d['id']+'"><h4>'+d['label']+' <b>'+str(first+rework)+'시간</b></h4><div class="benefit-bar" role="img" aria-label="'+e(d['label']+' 기본 처리'+str(first)+'시간, 추가 재작업'+str(rework)+'시간, 합계'+str(first+rework)+'시간')+'"><i class="benefit-first" style="width:'+str(float(first/F(3)))+'%"></i><i class="benefit-rework" style="width:'+str(float(rework/F(3)))+'%"></i></div><p>기본 '+str(first)+'시간 + 재작업 '+str(rework)+'시간</p></section>'
 out+='''</div><h3>사람의 비율과 작업의 비율을 섞지 않아요</h3><p>대상 사용자100명 중 교육 수료90명, 이번 달 합의한 실제 업무를1건 이상 끝낸 사용자는60명입니다. 수료율90%와 이 정의의 실사용률60%는 다른 지표예요. 사람별 요청량을 모르므로 “전체 요청의60%만 새 기능으로 처리했다”고 바꾸어 말할 수 없습니다. 계정 권한·업무 배정·사용 장벽은 별도 확인합니다.</p><div class="tco-table-scroll"><table class="benefit-targets"><caption>도입 전에 합의했다고 가정한 창작 목표 · 보편적인 합격 기준이 아닙니다</caption><thead><tr><th scope="col">지표</th><th scope="col">목표</th><th scope="col">현재 관찰</th></tr></thead><tbody><tr><th scope="row">실사용 사용자 / 대상 사용자</th><td>80% 이상</td><td>60/100 = 60% · 미달</td></tr><tr><th scope="row">1,200건의 경계 내 총 투입</th><td>220시간 이하</td><td>240시간 · 미달</td></tr><tr><th scope="row">재작업 요청 / 종료 요청</th><td>10% 이하</td><td>240/1,200 = 20% · 미달</td></tr></tbody></table></div><p>40시간 감소가 관찰돼도 목표 전체를 충족했다고 할 수 없습니다. 실제 전후 비교에서는 업무 구성·인력·계절·기록 누락·다른 개선의 영향을 확인해야 해요. 이 한 달 비교에는 무작위 대조가 없으므로 소프트웨어만의 인과 효과나 다음 달의 지속 효과를 확정하지 않습니다.</p><h3>40시간은 통장에 들어온 돈일까요?</h3><div class="benefit-ledgers"><section><span class="eyebrow">여력 · 시간 가치</span><h4>40시간 / 월</h4><p>다른 업무에 쓸 수 있는 잠정 여력입니다. 실제로 누구에게 언제 재배치됐고 어떤 결과를 냈는지 확인해요. 시간이 쪼개져 활용되지 못하거나 추가 지원 업무가 생길 수도 있습니다.</p><p>설명을 위한 시간당3만 원을 곱하면120만 원입니다. 이 값은 임의 단가로 환산한 시간 가치이며 줄어든 급여나 실현 매출이 아닙니다.</p></section><section><span class="eyebrow">현금 · 이 예제의 비교 경계</span><h4>월 지출 30만 원 증가</h4><p>급여·외주·초과근무 지급액은 그대로이고 새 서비스료가월30만 원 추가됐다고 가정합니다. 그 외 현금 변화가 없으면 이 경계의 현금 절감은0, 추가 지출은30만 원입니다.</p><p>120−30=90만 원을 “현금 절감”으로 보고할 수 없습니다. 초기 투자·세금·할인·다른 편익과 비용이 빠져 있으므로 전체 사업 ROI나 순현재가치도 계산하지 않습니다.</p></section></div><aside class="concept-trap"><b>같은40시간에 이름만 두 번 붙이지 않아요</b><p>운영팀이 “시간 절감40시간”, 제품팀이 같은 기록으로 “자동화 여력40시간”을 보고해도 합계80시간이 아닙니다. 동일 요청·기간·활동·증거를 가리키는지 확인하고 대표 편익과 다른 보고서의 참조 관계를 남깁니다. 두 팀의 독립된 추가 효과라는 증거가 있을 때만 별도로 평가해요.</p></aside><h3>프로젝트 뒤에도 측정이 이어지도록 넘겨요</h3><div class="tco-table-scroll"><table class="benefit-profile"><caption>창작 편익 기록의 최소 예시 · 회사 표준 양식이나 공식 시험 서식이 아닙니다</caption><tbody><tr><th scope="row">목적·경계</th><td>같은 품질의 접수 업무에서 활용 가능한 여력을 확보. 월간 적격1,200건의 기본 처리+추가 재작업.</td></tr><tr><th scope="row">기준·목표·근거</th><td>도입 전280시간과 재작업10%; 목표220시간 이하·재작업10% 이하. 정의·원시 기록·측정 버전 보존.</td></tr><tr><th scope="row">측정·검증 담당</th><td>운영 분석 담당이 시간/품질 자료를 확인하고 재무 담당이 실제 지출 변화를 별도로 대조.</td></tr><tr><th scope="row">편익 책임·사용 계획</th><td>운영 책임자가 여력 배치와 후속 결과를 담당. PM의 배포 종료가 그 책임을 없애지 않음.</td></tr><tr><th scope="row">검토·조건·결정</th><td>8주 차에 중간 검토, 이후 월간 추적을 합의. 인과 검증·재작업 원인·권한 장벽이 미확인. 계속·보완·중단의 권한자와 다음 검토일 기록.</td></tr></tbody></table></div><p>현재 기록 예: “배포와 운영 인계 완료. 이 가상 비교의 시간 감소는40시간, 재작업과 실사용 목표는 미달. 현금 절감 증거 없음. 운영 책임자가 품질 원인·실사용 장벽·자료 비교 가능성을 확인하고,8주 검토에서 후속 선택을 제시한다.” 편익 목표를 낮춰 과거를 성공으로 덮지 말고, 필요하면 기존 목표와 변경 근거·권한·새 버전을 함께 보존합니다.</p><h3>가정을 바꾸며 내 말로 판단하기</h3><p class="small muted">비채점 창작 연습 · 기존 판단 문제의 답과 별개입니다.</p>'''
 for q,a in [
 ('도입 후 재작업 비율만10%였다면 감소 시간은 얼마일까요?','추가 재작업은40시간, 합계는160+40=200시간입니다. 전280시간 대비80시간 감소입니다. 처음 계산과 달리 재작업 증가가 없는 별도 시나리오예요. 다른 조건을 함께 바꾼 결과처럼 쓰지 않습니다.'),
 ('교육90%·실사용60%면 요청의30%가 교육 효과를 못 봤다는 뜻인가요?','아닙니다. 두 값은 사람 단위이며 개인별 포함 관계·업무 배정·요청량·행동 원인을 모두 알려주지 않습니다. 단순 차이30%p를 요청 비율이나 교육의 인과 실패율로 해석하지 않습니다.'),
 ('절감 시간40시간의 급여 환산액120만 원을 현금 절감으로 잡아도 될까요?','지급 급여나 다른 지출이 줄었다는 증거가 없습니다. 시간 가치와 현금 흐름을 구분하고, 서비스료30만 원은 실제 현금 비용으로 별도 봅니다. 같은 시간의 가치를 다른 이름으로 중복 합산하지 않습니다.'),
 ('이 달에280→240시간이 됐으면 편익을 최종 확정하고 책임을 끝낼까요?','품질·채택 목표 미달과 비교 가능성·인과·지속성·활용 증거가 남아 있습니다. 합의한 운영 책임자·검토 주기·의사결정 권한으로 추적합니다. 배포 완료나 한 지표의 개선과 전체 편익 실현을 같은 상태로 표시하지 않습니다.')]:
  out+='<details class="think-box benefit-reflection"><summary>'+e(q)+'</summary><p>'+e(a)+'</p></details>'
 out+='<nav class="evidence-links" aria-label="편익 측정과 연결된 수업"><a class="text-link" href="pmp-lesson:n68">발견·실험의 근거 →</a><a class="text-link" href="pmp-lesson:n70">실행 장벽과 변화 수용 →</a><a class="text-link" href="pmp-lesson:n74">종료와 운영 전환 →</a><a class="text-link" href="pmp-lesson:n47">현재가치와 사업성 →</a></nav><details class="evidence-source-details"><summary>출처·판본·적용 범위</summary><ul class="source-list">'
 for s in SOURCES:out+='<li><a href="'+e(s['url'])+'" target="_blank" rel="noopener">'+e(s['title'])+'</a><p>'+e(s['note'])+'</p></li>'
 return out+'</ul><p class="small muted">요청·사용자·시간·재작업·환산 단가·서비스료·목표·기록·연습은 독립 제작입니다. 영국의 보고 분류와 조직 책임을 보편 규정으로 쓰지 않으며 실제 절감·재무 처리·특정 사업의 타당성을 입증하지 않습니다.</p></details></section>'
